*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#fff4f9,#f4e8fa);color:#492b47;font:15px/1.5 system-ui,sans-serif}main{max-width:780px;margin:auto;padding:20px 16px 45px}h1{font:700 39px Georgia,serif;margin:5px 0 12px}p{color:#806478}.eyebrow{font-size:11px;color:#a13c78;letter-spacing:2px;text-transform:uppercase;font-weight:800}.card{background:#fffbfd;border:1px solid #efd5e4;border-radius:20px;padding:18px;margin:12px 0}a{color:#95366d}.stats{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}.stats strong{display:block;font-size:22px;font-variant-numeric:tabular-nums}.stats span{font-size:12px;color:#806478}.deck{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:16px 0}.tile{border:1px solid #c68eb5;border-radius:15px;background:linear-gradient(145deg,#b86fa6,#8a4c9d);color:white;aspect-ratio:1;display:grid;place-items:center;cursor:pointer;font-size:clamp(22px,6vw,43px);transition:transform .2s;box-shadow:0 5px 0 #793f8240}.tile:focus-visible{outline:3px solid #7e3866;outline-offset:3px}.tile.open,.tile.matched{background:#fff4f7;color:#492b47;box-shadow:none;transform:rotateY(0)}.tile.matched{background:#e1f0e6;border-color:#93bb9c}.tile:disabled{cursor:default;opacity:1}.btn{font:inherit;border:0;border-radius:11px;padding:11px 17px;background:#a13c78;color:#fff;font-weight:700;cursor:pointer}.meta{font-size:12px;color:#806478}@media(max-width:400px){.deck{gap:7px}.tile{border-radius:10px}.card{padding:12px}}
</style></head><body><?=$masthead?><main><div class="studio-section-hero"><div><div class="eyebrow">Studio · Minijuegos</div><h1>Memory Chic</h1><p>Encontrá los ocho pares. Entrená tu memoria y superá tu propio récord.</p><a href="<?=studioEsc($base)?>minijuegos/">← Todos los minijuegos</a></div><?=studioArt('minijuegos')?></div><div class="card"><div class="stats"><div><span>Pares</span><strong id="pairs">0/8</strong></div><div><span>Movimientos</span><strong id="moves">0</strong></div><div><span>Tiempo</span><strong id="clock">0 s</strong></div><div><span>Mejor marca local</span><strong id="best">—</strong></div></div><div class="deck" id="deck"></div><p id="result" role="status">Tocá una ficha para empezar.</p><button class="btn" id="reset">Nueva partida</button><p class="meta">Juego libre de práctica. El récord queda en este navegador y todavía no entrega créditos de cuenta.</p></div></main><script>
'use strict';const $=id=>document.getElementById(id),icons=['👠','🎀','💄','👗','👜','🪞','💅','✨'];let cards=[],open=[],matched=new Set(),moves=0,start=0,finished=false,delay=0,timer=0,version=0;function record(){try{return JSON.parse(localStorage.getItem('studio-memory-best')||'null')}catch(e){return null}}function showBest(){const b=record();$('best').textContent=b?b.moves+' mov. / '+b.time+' s':'—'}function clock(){if(start&&!finished)$('clock').textContent=Math.floor((Date.now()-start)/1000)+' s'}function finish(){finished=true;clearInterval(timer);const time=Math.floor((Date.now()-start)/1000);$('clock').textContent=time+' s';const best=record();if(!best||moves<best.moves||moves===best.moves&&time<best.time){try{localStorage.setItem('studio-memory-best',JSON.stringify({moves,time}))}catch(e){}showBest();$('result').textContent='¡Álbum completo! Nueva mejor marca.'}else $('result').textContent='¡Encontraste los ocho pares!'}function draw(){const board=$('deck');board.replaceChildren();cards.forEach((icon,i)=>{const b=document.createElement('button'),visible=matched.has(i)||open.includes(i);b.type='button';b.className='tile'+(matched.has(i)?' matched':visible?' open':'');b.textContent=visible?icon:'✦';b.setAttribute('aria-label',visible?'Ficha '+(i+1)+' '+icon:'Ficha '+(i+1)+' oculta');b.disabled=matched.has(i)||open.includes(i)||finished;b.onclick=()=>turn(i);board.append(b)});$('pairs').textContent=matched.size/2+'/8';$('moves').textContent=moves}function turn(i){if(finished||open.length===2||matched.has(i)||open.includes(i))return;if(!start){start=Date.now();timer=setInterval(clock,250)}open.push(i);draw();if(open.length===2){moves++;const [a,b]=open,v=version;if(cards[a]===cards[b]){matched.add(a);matched.add(b);open=[];draw();if(matched.size===16)finish()}else{draw();delay=setTimeout(()=>{if(v!==version)return;open=[];draw()},650)}}}function reset(){version++;clearTimeout(delay);clearInterval(timer);cards=[...icons,...icons];for(let i=cards.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}open=[];matched=new Set();moves=0;start=0;finished=false;$('clock').textContent='0 s';$('result').textContent='Tocá una ficha para empezar.';showBest();draw()}$('reset').onclick=reset;reset();
</script></body></html>